    public function testEveryListedOperationHasARow(): void
    {
        $listed = array_values(array_filter(array_map('trim', file(__DIR__ . '/parity-operations.txt'))));
        $rows = array_map(static fn (array $row): string => $row[0], self::operations());

        $this->assertSame($listed, $rows);
        $this->assertCount(count(array_unique($rows)), $rows, 'an operation has two rows');
    }

    public function testEveryOperationHitsItsRoute(): void
    {
        foreach (self::operations() as [$key, $verb, $path, $body, $idem, $call]) {
            $mock = new MockClient();
            $mock->push(200, ['ok' => true]);
            $call(new Client('sk_test_123', 'https://api.atlas.test', $mock));

            $request = $mock->lastRequest();
            $this->assertSame($verb, $request->getMethod(), $key);
            $this->assertSame('https://api.atlas.test' . $path, (string) $request->getUri(), $key);
            $sent = (string) $request->getBody();
            if ($body === null) {
                $this->assertSame('', $sent, "{$key} should send no body");
            } else {
                $this->assertSame($body, json_decode($sent, true), "{$key} body");
                $this->assertSame('application/json', $request->getHeaderLine('Content-Type'), $key);
            }
            $this->assertSame($idem ? 'idem_1' : '', $request->getHeaderLine('Idempotency-Key'), "{$key} idempotency");
        }
    }
}
